export function parseRalplanAdvisoryInvocation(text) {
    const tokens = text.trim().split(/\s+/u);
    if (!/^\$(?:oh-my-codex:)?ralplan$/iu.test(tokens[0] ?? ''))
        return 'none';
    const args = tokens.slice(1);
    if (!args.some((token) => token.toLowerCase().startsWith('--advisory')))
        return 'none';
    return args.every((token) => /^--(?:advisory|interactive|deliberate)$/iu.test(token)
        || !token.startsWith('-') && !token.startsWith('$')) ? 'valid' : 'invalid';
}
export function isDirectRalplanAdvisoryInvocation(text) {
    return parseRalplanAdvisoryInvocation(text) === 'valid';

const advisoryInvocation = config.mode === 'ralplan'
    && isDirectRalplanAdvisoryInvocation(activationText);
if (config.mode === 'ralplan' && advisoryInvocation) {
    const sessionId = safeString(nextSkill.session_id).trim();
    const rootThreadId = safeString(nextSkill.thread_id).trim();
