    const pendingRecovery = prior?.corruption === 'rollover_pending_admin'
        || prior?.corruption === 'current_missing_with_advisory_state';
    if (prior?.corruption && !pendingRecovery)
        throw new Error(`ralplan_advisory_${prior.corruption}`);
    const activated = await activateOrResumeRalplanAdvisory({
        cwd: sourceCwd, sessionId, rootThreadId, activationTurnId,
        producer: 'native', threadKind: options.advisoryThreadKind ?? 'unknown',
        ...(prior?.activation?.generation_id ? { predecessorGenerationId: prior.activation.generation_id } : {}),
        nowIso, prompt: activationText,
        failpoint: async (checkpoint) => {
            if (checkpoint === 'after_intent' && !pendingRecovery) {
                await options.advisoryActivationFailpoint?.('rollover_intent');
            }
            if (checkpoint === 'after_mode')
                await options.advisoryAfterModeBindingFailpoint?.();
            if (checkpoint === 'intent_committed')
                await options.advisoryActivationFailpoint?.('intent_committed');
        },
    });
    const activation = activated.activation;
    baseState.workflow_variant = 'advisory';
    baseState.advisory_generation_id = activation.generation_id;
    baseState.execution_handoff_authorized = false;

if (hookEventName === "SubagentStart") {
    const parentId = readStrictStopPayloadSessionId(payload);
    const childId = normalizeSessionId(safeString(payload.agent_id).trim());
    const pointer = await readSessionPointer(resolveSessionPointerContext(cwd));
    const rootId = safeString(pointer.state?.native_session_id).trim();
    if (pointer.status !== "usable" || !pointer.state || !parentId || !childId
        || childId === parentId || parentId !== rootId) {
        await appendToLog(cwd, { event: "subagent_start_binding_rejected", timestamp: new Date().toISOString() });
        return { hookEventName, omxEventName: null, skillState: null, outputJson: null };
    }
    const sessionId = pointer.state.session_id;
    const role = safeString(payload.agent_type).trim();
    recordNativeSubagentAuthorityObservation(cwd, {
        sessionIds: [sessionId, parentId], childThreadId: childId,
        parentThreadId: parentId, rootNativeSessionId: rootId,
        authorityEvidence: "valid", mode: role,
    });
    const advisory = await readCurrentRalplanAdvisory(cwd, sessionId);
    const scope = advisory && !advisory.corruption && !advisory.fence
        && advisory.activation.root_thread_id === rootId
        ? `ralplan-advisory:${advisory.activation.generation_id}` : undefined;
    await recordSubagentTurnForSessionPartitions(cwd, {
        sessionId, threadId: childId, kind: "subagent", leaderThreadId: rootId,
        mode: role, ...(scope ? { scope } : {}),
    });
    await appendToLog(cwd, { event: "native_subagent_start_recorded", session_id: sessionId,
        native_session_id: childId, parent_thread_id: parentId, agent_role: role,
        ...(scope ? { scope } : {}), timestamp: new Date().toISOString() });
    return { hookEventName, omxEventName: null, skillState: null, outputJson: null };
}
if (hookEventName === "SubagentStop") {
    // This event names the parent session and child agent separately; it is not a leader Stop.
    const parentSessionId = readStrictStopPayloadSessionId(payload);
    const agentId = normalizeSessionId(safeString(payload.agent_id).trim());
    let sessionId = null;
    let pluginDiscoveryCwd;
    if (parentSessionId && agentId && agentId !== parentSessionId) {
        const authoritativeTeamWorker = hasRawTeamWorkerDeclaration()
            ? await resolveAuthoritativeTeamWorkerContext(cwd)
            : null;
        if (authoritativeTeamWorker) {
            // Team workers can own child agents without the shared leader pointer or tracker summary.
            sessionId = parentSessionId;
            pluginDiscoveryCwd = authoritativeTeamWorker.canonicalLeaderCwd;
        }
        else {
            const pointer = await readSessionPointer(resolveSessionPointerContext(cwd));
            if (pointer.status === "usable" && pointer.state && !sessionPointerAliases(pointer.state).has(agentId)) {
                const candidateSessionId = pointer.state.session_id;
                const summary = await readSubagentSessionSummary(cwd, candidateSessionId);
                if (payloadMatchesSessionPointer(parentSessionId, pointer.state)
                    || summary?.allThreadIds.includes(parentSessionId)) {
                    sessionId = candidateSessionId;
                }
            }
        }
    }
    if (sessionId && agentId) {
        try {
            await recordSubagentTurnForSessionPartitions(cwd, {
                sessionId,
                threadId: agentId,
                turnId: readPayloadTurnId(payload) || undefined,
                kind: "subagent",
                mode: safeString(payload.agent_type).trim() || undefined,
                completed: true,
                completionSource: "native_stop_event",
            });
        }
        catch (error) {
            await logNativeHookCliError(cwd, "native_subagent_completion_tracking_error", error, payload, { agent_id: agentId });
            return { hookEventName, omxEventName, skillState: null, outputJson: null };
        }
        if (!shouldSuppressSubagentLifecycleHookDispatch()) {

        }
    }
}
if (hookEventName === "UserPromptSubmit") {
    const prompt = readPromptText(payload);
    const advisoryThreadKind = promptTurnContext?.status === "authorized"
        && promptTurnContext.authorization.targetRelation !== "explicit-independent"
        && promptTurnContext.authorization.thread.kind === "root-or-drift"
        ? "root-or-drift" : "unknown";
    if (!isSubagentPromptSubmit)
        promptClassification = classifyKeywordInput(prompt);
    if (canonicalSessionId && !isSubagentPromptSubmit && advisoryStateDetection?.status === "normal") {
        try {
            await activateOrResumeRalplanAdvisory({
                cwd: policyCwd, sessionId: canonicalSessionId, rootThreadId: threadId,
                activationTurnId: turnId, prompt, resumeOnly: true, producer: "native", threadKind: advisoryThreadKind,
            });
            const advisory = await observeRalplanAdvisoryPrompt({
                cwd: policyCwd,
                sessionId: canonicalSessionId,
                turnId,
                threadId,
                prompt,
                producer: "native",
                threadKind: promptTurnContext?.status === "authorized"
                    && promptTurnContext.authorization.targetRelation !== "explicit-independent"
                    ? "root-or-drift" : "unknown",
                isSubagentPromptSubmit,
                markedContinuation: payload.continuation === true
                    || payload.is_continuation === true
                    || safeString(payload.source).toLowerCase().includes("continuation"),
                synthetic: payload.synthetic === true
                    || payload.auto_nudge === true
                    || safeString(payload.source).toLowerCase().includes("nudge"),
                reservedInput: promptClassification?.reservedInput ?? null,
            });
            if ((advisory.intent === "replan" || advisory.intent === "new_advisory")
                && advisory.projection?.activation) {
                const activated = await activateOrResumeRalplanAdvisory({
                    cwd: policyCwd, sessionId: canonicalSessionId, rootThreadId: threadId,
                    activationTurnId: turnId, prompt, producer: "native", threadKind: advisoryThreadKind,
                    predecessorGenerationId: advisory.projection.activation.generation_id,
                });
                if (activated)
                    advisory.projection = activated.projection;
            }
            const advisoryBinding = await readModeStateForSession("ralplan", canonicalSessionId, policyCwd);

// 0.5. Track leader + native subagent thread activity (lead session only)
if (!isTeamWorker && canWriteLeaderScopedState) {
    try {
        const threadId = safeString(payload['thread-id'] || payload.thread_id || '');
        const turnId = safeString(payload['turn-id'] || payload.turn_id || '');
        if (getEffectiveSessionId() && threadId) {
            const { recordSubagentTurnForSession } = await import('../subagents/tracker.js');
            const trackingPointer = await readSessionPointer(resolveSessionPointerContext(cwd));
            const canonicalLeader = trackingPointer.status === 'usable'
                && trackingPointer.state?.session_id === getEffectiveSessionId()
                ? trackingPointer.state.native_session_id : undefined;
            if (canonicalLeader) await recordSubagentTurnForSession(cwd, {
                leaderThreadId: canonicalLeader,
                kind: threadId === canonicalLeader ? 'leader' : 'subagent',
                preserveCompletionEvidence: true,
                sessionId: getEffectiveSessionId(),
                threadId,
                ...(turnId ? { turnId } : {}),
                timestamp: new Date().toISOString(),
                mode: safeString(payload.mode || ''),
